{"code":"function chooseBin(item, remainingCapacities) {
  let best = -1;
  let bestSlack = Infinity;
  for (let i = 0; i < remainingCapacities.length; i++) {
    const cap = remainingCapacities[i];
    if (cap >= item) {
      const slack = cap - item;
      if (slack < bestSlack) { bestSlack = slack; best = i; }
    }
  }
  if (best !== -1 && bestSlack > 20) {
    let altBest = -1;
    let altSlack = Infinity;
    for (let j = 0; j < remainingCapacities.length; j++) {
      const cap = remainingCapacities[j];
      if (cap >= item) {
        const slack = cap - item;
        if (slack < altSlack && slack >= bestSlack - 20) { altSlack = slack; altBest = j; }
      }
    }
    if (altBest !== -1) return altBest;
  }
  return best;
}","hypothesis":"Among bins with enough space, prefer one whose post-fill slack is within 20 of the tightest fit to better balance bins."}
